// Get the output string from the Research AI Agent
const outputString = $input.first().json.output;

// Parse the string into a JSON object
const parsedOutput = JSON.parse(outputString);

// Return the parsed JSON as a single item
return [{
  json: parsedOutput
}];

/*****************************************************************
 *  MERGE proposal split items  *****************************************************************/

const merged = {
  /* single‑value strings */
  title: '',
  introduction_background: '',
  problem_statement: '',
  ethics_considerations: '',
  expected_outcomes: '',

  /* arrays */
  problem_statement_structure: [],
  literature_review_themes: [],
  research_questions: [],
  references: [],
  suggested_reading: [],

  /* object */
  methodology_approach: {}
};

/* ---------- loop through every split item ---------- */
$input.all().forEach(item => {
  const d = item.json;

  /* scalar fields (last one wins) */
  if (d.title)                     merged.title                   = d.title;
  if (d.introduction_background)   merged.introduction_background = d.introduction_background;
  if (d.problem_statement)         merged.problem_statement       = d.problem_statement;
  if (d.ethics_considerations)     merged.ethics_considerations   = d.ethics_considerations;
  if (d.expected_outcomes)         merged.expected_outcomes       = d.expected_outcomes;

  /* array fields (accumulate) */
  const pushArray = (field) => {
    if (d[field]) {
      const arr = Array.isArray(d[field]) ? d[field] : [d[field]];
      merged[field].push(...arr);
    }
  };

  [
    'problem_statement_structure',
    'literature_review_themes',
    'research_questions',
    'references',
    'suggested_reading'
  ].forEach(pushArray);

  /* methodology_approach – first complete object wins */
  if (d.methodology_approach && !Object.keys(merged.methodology_approach).length) {
    merged.methodology_approach = d.methodology_approach;
  }
});

/* ---------- deduplicate arrays ---------- */
[
  'problem_statement_structure',
  'literature_review_themes',
  'research_questions',
  'references',
  'suggested_reading'
].forEach(key => {
  merged[key] = [...new Set(merged[key])];
});

/* ---------- output ---------- */
return [{ json: merged }];

/*********************************************************************
 * NWU  RESEARCH  PROPOSAL
 *********************************************************************/

/* ---------- helpers ---------- */
const esc = s => typeof s==='string'
  ? s.replace(/&/g,'&amp;').replace(/</g,'&lt;')
     .replace(/>/g,'&gt;').replace(/"/g,'&quot;')
     .replace(/'/g,'&#039;')
  : s;

/* ---------- palette & fonts ---------- */
// Brand Guidelines Mandated Colors
const P='#6C3D91';  // Primary Purple
const TQ='#00889C'; // Secondary Turquoise
const GY='#78848E'; // Grey
const TXT='#2F373D';// Dark Text
const BG='#F8FAFC'; // Light Background

// Font Stacks (Prioritizing Professional & Widely Available)
const HEADING_FONT='"Trebuchet MS", Trebuchet, Arial, sans-serif';
// **Changed to Times New Roman**
const BODY_FONT='"Times New Roman", Times, serif';

/* ---------- proposal JSON ---------- */
const p = $('Parse Research Output').first().json;

/* ---------- file meta ---------- */
const today = new Date().toISOString().slice(0, 10);
// Add basic check for p.title before using it
const titleForSlug = p && p.title ? p.title : 'proposal';
const slug = titleForSlug.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const fileName = `nwu-proposal-${slug}-${today}.pdf`;

/* ---------- html ---------- */
const htmlContent = `
