  color:#2F373D;
  background:#fff;
  -webkit-font-smoothing:antialiased;
  -moz-osx-font-smoothing:grayscale;
}
/* =====  TYPOGRAPHY  ===== */
h1,h2,h3,h4,h5,h6{
  font-family:"Trebuchet MS",Trebuchet,Arial,sans-serif;
  margin:0 0 .5em 0;font-weight:600;color:#6C3D91;text-align:left;
}
