  width: 100%;
  min-height: 100%; /* Ensures full vertical fill */
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background: linear-gradient(135deg, #6C3D91 0%, #00889C 100%);
  color: #fff;
  text-align: center;
}
.cover .logo-box{
  background:rgba(255,255,255,.95);border-radius:6px;padding:15px 35px;
  margin-bottom:40px;box-shadow:0 4px 15px rgba(0,0,0,.1);
}
.cover .logo-box img{height:65px;display:block;}
.cover h1{font-size:26pt;margin-bottom:15px;color:#fff; margin: 0 20mm 15px 20mm; text-align: center;}
.cover p.date{font-size:12pt;opacity:.9;margin:0;color:#fff;text-align: center;}

/* =====  RUNNING HEADER  ===== */
