  position:running(runningHeader);   /* captured for margin box */
  display:none;                      /* remove from normal flow */
}
.header-bar-content{                 /* visible header clone */
  height:40px;background:#6C3D91;color:#fff;
  display:flex;align-items:center;padding:0 20mm;font-size:9pt;
}
.header-bar-content img{height:22px;margin-right:12px;}
.header-bar-content span{
  font-family:"Trebuchet MS",Trebuchet,Arial,sans-serif;
  font-variant:small-caps;letter-spacing:.5px;overflow:hidden;
  white-space:nowrap;text-overflow:ellipsis;
  text-align:left;
}

/* =====  FRONT‑MATTER  ===== */
.frontmatter{
  padding:25mm 20mm 0 20mm;
  page-break-inside:avoid;
  page-break-after:always;
}
.toc,.summary{margin-bottom:30px;page-break-inside:avoid;}

/* TOC */
.toc h3{color:#00889C;margin-bottom:15px;}
.toc ul{
  columns:2 200px;column-gap:30px;list-style:none;margin:0;padding:0;
  counter-reset:item;
}
.toc li{margin-bottom:8px;font-size:10.5pt;break-inside:avoid-column;}
.toc li::before{
  content:counters(item,\".\")\" \";counter-increment:item;
  color:#6C3D91;font-weight:600;min-width:20px;display:inline-block;
}

/* SUMMARY PANELS */
.summary{border-left:5px solid #00889C;background:#F8FAFC;padding:20px 25px;}
.summary h3{margin-bottom:12px;}
.summary p{font-size:10.5pt;line-height:1.5;}
.summary ul{margin:0;padding-left:25px;}

/* =====  MAIN WRAPPER  ===== */
.wrap{padding:calc(40px + 20mm) 20mm 25mm 20mm;} /* top padding = header height */

/* SECTIONS */
.section{margin-bottom:40px;}
.section h2{margin-top:0;}
.cols2{columns:2 200px;column-gap:30px;margin:0 0 1em 0;}
.cols2 li{break-inside:avoid-column;padding-left:5px;}

/* TABLE */
.table{
  width:100%;border-collapse:collapse;font-size:10.5pt;margin:15px 0 1em 0;
}
.table td{border:1px solid #ddd;padding:10px 12px;vertical-align:top;line-height:1.5;}
.table td.head{
  background:#6C3D91;color:#fff;font-family:\"Trebuchet MS\",Trebuchet,Arial,sans-serif;
  font-variant:small-caps;font-size:10pt;width:25%;border-color:#6C3D91;
}

/* REFERENCES */
.ref-list{list-style:none;padding-left:0;font-size:10pt;line-height:1.5;}
.ref-list li{padding-left:2.5em;text-indent:-2.5em;margin-bottom:.8em;}
</style>
</head>
<body>

<!-- =====  COVER  ===== -->
<div class="cover">
  <div class="logo-box">
    <img src="https://services.nwu.ac.za/sites/services.nwu.ac.za/files/files/designs-branding/NWU-holding-shape-digital-white.png" alt="NWU Logo">
  </div>
  <h1>${esc(p?.title)}</h1>
  <p class="date">${today}</p>
</div>

<!-- =====  RUNNING HEADER SOURCE (hidden)  ===== -->
<div class="header-bar">
  <!-- nothing; this element is captured by running(runningHeader) -->
</div>

<!-- =====  VISIBLE HEADER ON EVERY PAGE  ===== -->
<div class="header-bar-content">
  <img src="https://services.nwu.ac.za/sites/services.nwu.ac.za/files/files/designs-branding/NWU-holding-shape-digital-white.png" alt="NWU">
